UPDATE runtime_delivery_units SET status='rejected',updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='sending' AND EXISTS(SELECT 1 FROM runtime_operations WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='delivering' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER));